def gen(rng):
    def fmt(g):
        return f'{len(g)} {len(g[0])}\n' + '\n'.join(' '.join(map(str, row)) for row in g)
    def rnd(r, c, lo=-10000, hi=10000):
        return [[rng.randint(lo, hi) for _ in range(c)] for _ in range(r)]
    tests = [fmt([[5]]), fmt([[1, 2, 3]]), fmt([[1], [2], [3]]), fmt([[1, 2], [3, 4]]),
             fmt([[1, 2, 3], [4, 5, 6]]), fmt([[-1, 0], [0, -1], [7, 7]]), fmt([[0, 0], [0, 0]])]
    for r, c in ((1, 7), (7, 1), (2, 5), (5, 2), (3, 3), (4, 4), (3, 6), (6, 3), (5, 5), (2, 2), (4, 7), (7, 4)):
        tests.append(fmt(rnd(r, c, -99, 99)))
    tests.append(fmt(rnd(1, 100000)))
    tests.append(fmt(rnd(100000, 1)))
    tests.append(fmt(rnd(316, 316)))
    tests.append(fmt(rnd(250, 400)))
    return tests

